\title{Tropical Convexity, Box Helly Theorems,\\and Canonical Feasibility Certificates}
\author{Aristotle}
\date{August 3, 2026}

\begin{document}
\maketitle

\begin{abstract}
We study normalized max-plus tropical convexity in finite-dimensional real space and isolate a class for which intersection and optimization admit exact certificates: products of closed coordinate intervals. A normalized tropical combination of $x,y\in\R^d$ has coordinates $\max\{x_i,t+y_i\}$ for $t\leq0$. We define tropical segments, convex sets, and finite tropical convex hulls. Arbitrary intersections of tropically convex sets remain tropically convex; every coordinate box is tropically convex; and every finite tropical convex hull is tropically convex by a max-distributivity identity. Our central result is a Helly theorem with Helly number $2$ for finite families of tropical boxes: total intersection is nonempty if and only if every pair intersects. For a nonempty family, feasibility is equivalent to $\ell_{p,i}\leq u_{q,i}$ for every $p,q,i$. When feasible, $x_i^*=\max_k\ell_{k,i}$ is a canonical common point and is coordinatewise least among all points satisfying the lower bounds. When infeasible, two boxes and one coordinate form a certificate. This yields an $O(nd)$ algorithm for $n$ boxes in dimension $d$.
\end{abstract}

\section{Introduction}

In max-plus algebra, tropical addition and multiplication are
\[
a\oplus b=\max(a,b),\qquad a\odot b=a+b.
\]
The algebra models systems in which parallel alternatives compete through a maximum while serial effects accumulate through addition, including synchronization, scheduling, and bottleneck systems. Tropical segments are generally bent piecewise-linear paths, and tropical polytopes are upper envelopes of shifted generators.

This paper develops normalized max-plus convexity and then gives a complete intersection theory for coordinate boxes. Four conclusions drive the account. Arbitrary intersections preserve tropical convexity. Coordinate boxes and finitely generated tropical convex hulls are tropically convex. A finite box family intersects globally exactly when it intersects pairwise. Finally, the coordinatewise maximum of all lower bounds is a canonical feasible point, while failure has a two-box certificate.

The unusually small Helly number comes from separability. Tropical convexity places boxes naturally in max-plus geometry; their Cartesian product structure allows the intersection question to be solved one coordinate at a time.

\section{Max-plus convexity}

Throughout, points of $\R^d$ are denoted $x=(x_1,\ldots,x_d)$.

\begin{definition}[Normalized tropical combination]
For $x,y\in\R^d$ and $t\leq0$, define
\[
C_t(x,y)_i=\max\{x_i,t+y_i\},\qquad i=1,\ldots,d.
\]
\end{definition}

\begin{definition}[Tropical segment]
The tropical segment between $x$ and $y$ is
\[
[x,y]_{\trop}=\{C_t(x,y):t\leq0\}\cup\{C_s(y,x):s\leq0\}.
\]
The two orderings symmetrize the normalization: one coefficient is fixed at zero and the other is nonpositive.
\end{definition}

\begin{definition}[Tropical convexity]
A set $S\subseteq\R^d$ is tropically convex if $C_t(x,y)\in S$ whenever $x,y\in S$ and $t\leq0$.
\end{definition}

\begin{definition}[Finite tropical convex hull]
For $m\geq1$ and points $p^{(1)},\ldots,p^{(m)}\in\R^d$, define
\[
\tconv\{p^{(1)},\ldots,p^{(m)}\}
=
\left\{z:\exists w_1,\ldots,w_m\in\R,
\ z_i=\max_{1\leq k\leq m}(w_k+p_i^{(k)})\ \forall i\right\}.
\]
A hull point is thus an upper envelope of translated generators.
\end{definition}

\begin{proposition}[Intersection closure]
The intersection of any family of tropically convex subsets of $\R^d$ is tropically convex.
\end{proposition}
\begin{proof}
If $x$ and $y$ lie in every member $S_\alpha$ of the family, tropical convexity of each $S_\alpha$ puts $C_t(x,y)$ in every $S_\alpha$ for every $t\leq0$. Hence the combination lies in their intersection.
\end{proof}

\section{Finite tropical hulls}

\begin{lemma}[Envelope combination identity]
For finite real families $a_k,b_k,c_k$ and any $t\in\R$,
\[
\max\left\{\max_k(a_k+c_k),\ t+\max_k(b_k+c_k)\right\}
=
\max_k\left(\max\{a_k,t+b_k\}+c_k\right).
\]
\end{lemma}
\begin{proof}
Addition by $t$ commutes with a finite maximum. The maximum of two maxima over the same index set is the maximum of the pairwise maxima, and
$\max\{a_k+c_k,t+b_k+c_k\}=\max\{a_k,t+b_k\}+c_k$.
\end{proof}

\begin{theorem}[Tropical convexity of finite tropical hulls]
The tropical convex hull of every nonempty finite family of points in $\R^d$ is tropically convex.
\end{theorem}
\begin{proof}
Represent two hull points by weights $u_k$ and $v_k$:
\[
z_i^{(1)}=\max_k(u_k+p_i^{(k)}),\qquad
z_i^{(2)}=\max_k(v_k+p_i^{(k)}).
\]
For $t\leq0$, set $r_k=\max\{u_k,t+v_k\}$. The envelope identity gives
\[
C_t(z^{(1)},z^{(2)})_i=\max_k(r_k+p_i^{(k)}).
\]
This is another valid hull representation.
\end{proof}

\section{Tropical boxes}

\begin{definition}[Coordinate box]
For $\ell,u\in\R^d$, let
\[
B(\ell,u)=\prod_{i=1}^d[\ell_i,u_i]
=\{x\in\R^d:\ell_i\leq x_i\leq u_i\text{ for all }i\}.
\]
The box is empty exactly when $\ell_i>u_i$ for some coordinate.
\end{definition}

\begin{theorem}[Tropical convexity of boxes]
Every coordinate box is tropically convex.
\end{theorem}
\begin{proof}
Take $x,y\in B(\ell,u)$ and $t\leq0$. For $z_i=\max\{x_i,t+y_i\}$,
\[
z_i\geq x_i\geq\ell_i.
\]
Also $x_i\leq u_i$ and $t+y_i\leq y_i\leq u_i$, so $z_i\leq u_i$. Thus $z\in B(\ell,u)$.
\end{proof}

Together with intersection closure, this shows that every intersection of tropical boxes is tropically convex.

\section{The interval theorem}

\begin{theorem}[Helly theorem for closed intervals]
Let $I_k=[a_k,b_k]$ be a finite family of closed real intervals. If
\[
a_i\leq b_j\qquad\text{for all }i,j,
\]
then all intervals have a common point. For a nonempty family, $x^*=\max_k a_k$ belongs to every interval. Consequently, pairwise intersection implies total intersection.
\end{theorem}
\begin{proof}
Every $a_k\leq x^*$. For fixed $j$, all $a_k\leq b_j$, and hence their maximum satisfies $x^*\leq b_j$. Thus $x^*\in I_j$ for every $j$. If every pair intersects, a point in $I_i\cap I_j$ lies above $a_i$ and below $b_j$, giving every required cross inequality. The converse is immediate.
\end{proof}

\section{The box Helly theorem}

Let
\[
B_k=\prod_{i=1}^d[\ell_{k,i},u_{k,i}],\qquad k=1,\ldots,n.
\]

\begin{lemma}[Pairwise intersection implies cross bounds]
If $B_p\cap B_q\neq\varnothing$, then $\ell_{p,i}\leq u_{q,i}$ for every coordinate $i$.
\end{lemma}
\begin{proof}
For $x\in B_p\cap B_q$, one has $\ell_{p,i}\leq x_i\leq u_{q,i}$.
\end{proof}

\begin{theorem}[Tropical Box Helly Theorem]
For every finite family of coordinate boxes in $\R^d$, the total intersection is nonempty if and only if every pairwise intersection is nonempty. Hence the Helly number of tropical boxes is at most $2$.
\end{theorem}
\begin{proof}
A common point clearly lies in every pair. Conversely, assume every pair intersects. The preceding lemma gives
\[
\ell_{p,i}\leq u_{q,i}\qquad\text{for all }p,q,i.
\]
Fix $i$. The coordinate intervals $[\ell_{k,i},u_{k,i}]$ satisfy the interval theorem and therefore share a value $x_i$. Choosing such a value independently for every coordinate produces $x\in B_k$ for every $k$.
\end{proof}

\begin{remark}[Sharpness]
In positive dimension, the bound cannot be reduced to $1$. Two nonempty boxes may be disjoint; for example, use $[0,1]$ and $[2,3]$ in the first coordinate and common nonempty intervals in all other coordinates.
\end{remark}

\section{Exact feasibility and the canonical point}

Assume $n\geq1$ and define
\[
x_i^*=\max_{1\leq k\leq n}\ell_{k,i}.
\]

\begin{lemma}[Lower-bound dominance]
For every $k,i$, one has $\ell_{k,i}\leq x_i^*$.
\end{lemma}
\begin{proof}
The left side is one of the terms defining the maximum.
\end{proof}

\begin{lemma}[Least point satisfying all lower bounds]
If $x$ satisfies $\ell_{k,i}\leq x_i$ for every $k,i$, then $x_i^*\leq x_i$ for every $i$.
\end{lemma}
\begin{proof}
Every term in the maximum defining $x_i^*$ is at most $x_i$.
\end{proof}

\begin{theorem}[Exact cross-bound characterization]
A nonempty finite family of boxes has a common point if and only if
\[
\ell_{p,i}\leq u_{q,i}
\qquad\text{for every }p,q,i.
\]
Whenever these inequalities hold, $x^*$ belongs to every box.
\end{theorem}
\begin{proof}
A common point $x$ gives $\ell_{p,i}\leq x_i\leq u_{q,i}$. Conversely, the canonical point dominates every lower bound. For fixed $q,i$, every $\ell_{p,i}\leq u_{q,i}$, so taking the maximum over $p$ yields $x_i^*\leq u_{q,i}$. Hence $\ell_{q,i}\leq x_i^*\leq u_{q,i}$ for all $q,i$.
\end{proof}

\begin{corollary}[Equivalent feasibility criteria]
For a nonempty finite family of boxes, the following are equivalent:
\begin{enumerate}[label=(\roman*)]
\item the total intersection is nonempty;
\item every pair intersects;
\item every cross inequality $\ell_{p,i}\leq u_{q,i}$ holds;
\item for every coordinate $i$,
\[
\max_k\ell_{k,i}\leq\min_k u_{k,i}.
\]
\end{enumerate}
\end{corollary}
\begin{proof}
The first three equivalences follow from the box Helly theorem and the cross-bound characterization. The last condition compresses all cross inequalities in a fixed coordinate into one extremal comparison.
\end{proof}

\section{Monotone optimization}

\begin{definition}[Coordinatewise monotone objective]
A function $F:\R^d\to\R$ is coordinatewise nondecreasing if $x_i\leq y_i$ for all $i$ implies $F(x)\leq F(y)$. It is coordinatewise strictly increasing if, in addition, $x\neq y$ implies $F(x)<F(y)$.
\end{definition}

\begin{theorem}[Canonical monotone optimality]
If a nonempty finite box family is feasible, its canonical lower point minimizes every coordinatewise nondecreasing objective on the common feasible region. For a coordinatewise strictly increasing objective, it is the unique minimizer.
\end{theorem}
\begin{proof}
Every feasible $x$ satisfies all lower bounds, so the least-point lemma gives $x^*\leq x$ coordinatewise. Apply monotonicity. Under strict monotonicity, equality of objective values forces $x=x^*$.
\end{proof}

Positive weighted sums are strictly increasing examples. The maximum coordinate is nondecreasing but need not produce a unique minimizer.

\section{Infeasibility certificates and algorithms}

\begin{theorem}[Two-box infeasibility certificate]
If a finite box family has empty total intersection, then two boxes already have empty intersection. More precisely, there exist $p,q,i$ such that
\[
\ell_{p,i}>u_{q,i}.
\]
\end{theorem}
\begin{proof}
This is the contrapositive of the box Helly theorem. Constructively, infeasibility implies
\[
\max_k\ell_{k,i}>\min_k u_{k,i}
\]
for some $i$. Choose $p$ attaining the maximum and $q$ attaining the minimum. No point can satisfy the two resulting bounds in coordinate $i$.
\end{proof}

\begin{algorithm}[Canonical feasibility and certificate scan]
For every coordinate $i$, find $p_i$ maximizing $\ell_{k,i}$ and $q_i$ minimizing $u_{k,i}$. Set
\[
L_i=\ell_{p_i,i},\qquad U_i=u_{q_i,i}.
\]
If $L_i>U_i$, return $(p_i,q_i,i)$ as an infeasibility certificate. If no coordinate fails, return $L=(L_1,\ldots,L_d)$ as a common feasible point.
\end{algorithm}

\begin{theorem}[Algorithm correctness and complexity]
The scan returns a common point exactly when the family is feasible. Every returned triple identifies two disjoint boxes. Its running time is $O(nd)$ and its auxiliary storage is $O(d)$, or $O(1)$ beyond streamed output.
\end{theorem}
\begin{proof}
If all $L_i\leq U_i$, then for every box $k$,
\[
\ell_{k,i}\leq L_i\leq U_i\leq u_{k,i},
\]
so $L$ lies in every box. A common point would satisfy $L_i\leq x_i\leq U_i$, so it cannot exist if $L_i>U_i$. In that case the maximizing lower box and minimizing upper box are disjoint. The scan examines two arrays of length $n$ in each of $d$ coordinates, giving $O(nd)$ time. Since the explicit input has $2nd$ scalar entries, this is asymptotically optimal.
\end{proof}

\section{Applications}

In scheduling, $x_i$ may represent the start time of task $i$, while different policies impose lower and upper windows. The canonical schedule uses the latest lower requirement for each task. An inconsistency is explained by two policies and one task. In resource allocation, coordinates represent allocated quantities, and the canonical point meets all lower service requirements at minimum coordinatewise levels. In robust parameter selection, each scenario supplies a permissible box; pairwise compatibility then guarantees a parameter vector valid in every scenario.

The results also fit discrete-event systems. A normalized max-plus combination models competition between one state and a delayed second state, with the later event winning coordinatewise. Tropical convexity of boxes says that coordinate windows remain stable under this operation.

\section{Discussion}

Three layers should be distinguished. The tropical hull theorem is algebraic: a maximum of weighted upper envelopes can be reorganized into one weighted upper envelope. Box convexity is order-theoretic: an unshifted term protects lower bounds, while a nonpositive shift protects upper bounds. The Helly number $2$ is a product phenomenon: coordinate independence reduces the problem to intervals.

Accordingly, the box theorem does not assert the same bound for arbitrary tropically convex sets. General tropical sets may couple coordinates through piecewise-linear relations. The present treatment also stays in $\R^d$, rather than adjoining $-\infty$ as a tropical zero. Completed max-plus spaces require additional endpoint conventions.

For an empty constraint family, feasibility holds conventionally, although a maximum of lower endpoints is not defined. In zero dimensions there is a unique point, and the coordinatewise claims are vacuous.

\section{Future directions}

One explicit conjectural property in the present framework is that testing every subfamily of size at most $2d$ suffices for arbitrary normalized max-plus tropically convex subsets of $\R^d$. This is a proposed target rather than a result of the box theory above.

\begin{enumerate}
\item Resolve the $2d$ conjectural bound and determine whether the sharper threshold $d+1$ is valid for normalized max-plus tropically convex sets when $d>0$.
\item Develop sharpness examples systematically; for boxes in positive dimension, two disjoint nonempty boxes already show that the number $2$ cannot be reduced.
\item Extend monotone-objective optimality to broader objective classes and analyze sensitivity under perturbations of lower and upper bounds.
\item Add coupled difference constraints $x_i-x_j\leq c$ and seek infeasibility certificates whose size depends only on $d$.
\item Relate support bounds for tropical convex hulls to small separation certificates and then to general tropical Helly principles.
\end{enumerate}

\section{Conclusion}

Normalized max-plus convexity has a concise structural theory. Arbitrary intersections, coordinate boxes, and finite tropical convex hulls are tropically convex. For boxes, pairwise intersection, global intersection, all cross-bound inequalities, and extremal coordinate comparisons are equivalent. The largest lower endpoint in each coordinate forms a canonical feasible point and the least point satisfying all lower constraints. It minimizes every coordinatewise nondecreasing objective. If feasibility fails, one coordinate and two boxes expose the contradiction. Thus a large tropical box system either has a canonical solution or fails for a reason with a constant-size certificate.

