def canonical_feasibility(boxes: Sequence[Box]) -> Vector | Certificate:
    if not boxes:
        return ()
    d = len(boxes[0].lower)
    if any(len(b.lower) != d or len(b.upper) != d for b in boxes):
        raise ValueError("inconsistent dimensions")
    point: list[float] = []
    for i in range(d):
        p = max(range(len(boxes)), key=lambda k: boxes[k].lower[i])
        q = min(range(len(boxes)), key=lambda k: boxes[k].upper[i])
        lower, upper = boxes[p].lower[i], boxes[q].upper[i]
